"""ABI type parsing, token parsing, encoding and decoding.

This module is a standalone implementation; it needs only Python's standard
library.  Integers are kept as unsigned 256-bit words, including signed tokens.
"""
from dataclasses import dataclass
import re


class AbiError(Exception):
    pass


def invalid():
    raise AbiError('Invalid data')


def caused(label, detail):
    raise AbiError(f'{label}: {detail}\n\nCaused by:\n    {detail}')


def rust_char(c):
    # Formatting used for a byte reported as an invalid hexadecimal character.
    special = {'\n': r'\n', '\r': r'\r', '\t': r'\t', '\0': r'\0', "'": r"\'", '\\': r'\\'}
    if c in special:
        return "'" + special[c] + "'"
    if not c.isprintable():
        return "'\\u{" + format(ord(c), 'x') + "}'"
    return "'" + c + "'"


def unhex(text, wrapped=False, prefix=False):
    if prefix and text.startswith('0x'):
        text = text[2:]
    data = text.encode('utf-8', 'surrogateescape')
    detail = None
    if len(data) % 2:
        detail = 'Odd number of digits'
    else:
        for i, b in enumerate(data):
            if b not in b'0123456789abcdefABCDEF':
                detail = f'Invalid character {rust_char(chr(b))} at position {i}'
                break
    if detail is not None:
        if wrapped:
            caused('Hex parsing error', detail)
        raise AbiError(detail)
    return bytes.fromhex(text)


@dataclass(frozen=True)
class Type:
    kind: str
    size: int = 0
    children: tuple = ()

    def __str__(self):
        if self.kind in ('int', 'uint', 'fixedbytes'):
            return ('bytes' if self.kind == 'fixedbytes' else self.kind) + str(self.size)
        if self.kind == 'array':
            return str(self.children[0]) + '[]'
        if self.kind == 'fixedarray':
            return str(self.children[0]) + '[' + str(self.size) + ']'
        if self.kind == 'tuple':
            return '(' + ','.join(map(str, self.children)) + ')'
        return self.kind

    def dynamic(self):
        if self.kind in ('bytes', 'string', 'array'):
            return True
        if self.kind == 'fixedarray':
            return self.children[0].dynamic()
        if self.kind == 'tuple':
            return any(c.dynamic() for c in self.children)
        return False


def parse_size(s):
    if not s:
        caused('Integer parsing error', 'cannot parse integer from empty string')
    if not re.fullmatch(r'\+?[0-9]+', s):
        caused('Integer parsing error', 'invalid digit found in string')
    value = int(s)
    if value > (1 << 64) - 1:
        caused('Integer parsing error', 'number too large to fit in target type')
    return value


def parse_type(s):
    if s.endswith(']'):
        start = s.rfind('[')
        if start < 0:
            size = parse_size(s[:-1])
            return Type('fixedarray', size, (parse_type(''),))
        length = s[start + 1:-1]
        subtype = parse_type(s[:start])
        if length == '':
            return Type('array', children=(subtype,))
        return Type('fixedarray', parse_size(length), (subtype,))
    if s.endswith(')'):
        if not s.startswith('('):
            raise AbiError('Invalid name: ' + s)
        # Components are separated only at the current nesting level.
        parts = []
        level = 0
        start = 1
        for i, c in enumerate(s[1:], 1):
            if c == '(':
                level += 1
            elif c == ')':
                if level:
                    level -= 1
                else:
                    if start < i:
                        parts.append(parse_type(s[start:i]))
                    start = i + 1
            elif c == ',' and level == 0:
                if start < i:
                    parts.append(parse_type(s[start:i]))
                start = i + 1
        return Type('tuple', children=tuple(parts))
    if s in ('address', 'bool', 'string', 'bytes'):
        return Type(s)
    if s == 'tuple':
        return Type('tuple')
    if s in ('uint', 'int'):
        return Type(s, 256)
    for prefix, kind in [('uint', 'uint'), ('int', 'int'), ('bytes', 'fixedbytes')]:
        if s.startswith(prefix):
            return Type(kind, parse_size(s[len(prefix):]))
    # User-defined Solidity enums appear in some ABIs as names.
    return Type('uint', 8)


@dataclass
class Token:
    kind: str
    value: object

    def dynamic(self):
        if self.kind in ('bytes', 'string', 'array'):
            return True
        if self.kind in ('fixedarray', 'tuple'):
            return any(t.dynamic() for t in self.value)
        return False

    def __str__(self):
        if self.kind in ('uint', 'int'):
            return format(self.value, 'x')
        if self.kind == 'bool':
            return 'true' if self.value else 'false'
        if self.kind in ('bytes', 'fixedbytes', 'address'):
            return self.value.hex()
        if self.kind == 'string':
            return self.value
        if self.kind == 'tuple':
            return '(' + ','.join(map(str, self.value)) + ')'
        return '[' + ','.join(map(str, self.value)) + ']'


MODULUS = 1 << 256


def decimal(s):
    if not re.fullmatch('[0-9]*', s):
        raise AbiError('Uint parse error: InvalidCharacter')
    n = int(s or '0')
    if n >= MODULUS:
        raise AbiError('Uint parse error: InvalidLength')
    return n


def parse_uint(s):
    match = re.fullmatch(r'([0-9]+)(?:\.([0-9]+))?\s*(wei|gwei|nano|ether)', s)
    if not match:
        return decimal(s)
    whole, fraction, unit = match.groups()
    precision = {'wei': 0, 'gwei': 9, 'nano': 9, 'ether': 18}[unit]
    fraction = fraction or ''
    if len(fraction) > precision:
        raise AbiError('Uint parse error: InvalidCharacter')
    return decimal(whole + fraction.ljust(precision, '0'))


def split_tokens(s, opening, closing):
    if not s.startswith(opening) or not s.endswith(closing):
        invalid()
    if len(s) == 2:
        return []
    result = []
    start = 1
    level = 0
    quoted = False
    for i, c in enumerate(s):
        if c == '"':
            quoted = not quoted
        elif not quoted:
            if c in '[(':
                level += 1
            elif c in '])':
                level -= 1
                if level == 0:
                    result.append(s[start:i])
                    start = i + 1
            elif c == ',' and level == 1:
                result.append(s[start:i])
                start = i + 1
    if quoted:
        invalid()
    return result


def tokenize(typ, text, lenient=False):
    kind = typ.kind
    if kind in ('uint', 'int'):
        try:
            b = unhex(text, wrapped=True)
            if len(b) != 32:
                invalid()
            return Token(kind, int.from_bytes(b, 'big'))
        except AbiError:
            if not lenient:
                raise
        if kind == 'uint':
            return Token(kind, parse_uint(text))
        negative = text.startswith('-')
        value = decimal(text.lstrip('-') if negative else text)
        if value > (1 << 255) or (value == 1 << 255 and not negative):
            raise AbiError('int256 parse error: ' + ('Underflow' if negative else 'Overflow'))
        return Token(kind, (-value if negative else value) % MODULUS)
    if kind in ('address', 'bytes', 'fixedbytes'):
        value = unhex(text, wrapped=True, prefix=True)
        if kind == 'address' and len(value) != 20:
            invalid()
        if kind == 'fixedbytes' and len(value) != typ.size:
            invalid()
        return Token(kind, value)
    if kind == 'bool':
        if text not in ('true', 'false', '0', '1'):
            invalid()
        return Token(kind, text in ('true', '1'))
    if kind == 'string':
        return Token(kind, text)
    if kind == 'tuple':
        parts = split_tokens(text, '(', ')')
        if len(parts) > len(typ.children):
            invalid()
        return Token(kind, [tokenize(t, v, lenient) for t, v in zip(typ.children, parts)])
    parts = split_tokens(text, '[', ']')
    tokens = [tokenize(typ.children[0], v, lenient) for v in parts]
    if kind == 'fixedarray' and len(tokens) != typ.size:
        invalid()
    return Token(kind, tokens)


def word(n):
    return n.to_bytes(32, 'big')


def pad(data):
    return data + b'\0' * ((-len(data)) % 32)


def encode_one(token):
    kind, value = token.kind, token.value
    if kind in ('uint', 'int', 'bool'):
        return word(int(value))
    if kind == 'address':
        return b'\0' * 12 + value
    if kind == 'fixedbytes':
        return pad(value)
    if kind in ('bytes', 'string'):
        b = value.encode('utf-8') if kind == 'string' else value
        return word(len(b)) + pad(b)
    if kind == 'array':
        return word(len(value)) + encode(value)
    return encode(value)


def encode(tokens):
    items = [(t.dynamic(), encode_one(t)) for t in tokens]
    offset = sum(32 if dynamic else len(b) for dynamic, b in items)
    heads, tails = [], []
    for dynamic, b in items:
        if dynamic:
            heads.append(word(offset))
            tails.append(b)
            offset += len(b)
        else:
            heads.append(b)
    return b''.join(heads + tails)


EMPTY_ERROR = ("Invalid name: please ensure the contract and method you're calling exist! "
               "failed to decode empty bytes. if you're using jsonrpc this is likely due to "
               "jsonrpc returning `0x` in case contract or method don't exist")


def take(data, offset, length):
    if offset < 0 or length < 0 or offset + length > len(data):
        invalid()
    return data[offset:offset + length]


def offset_word(data, offset):
    b = take(data, offset, 32)
    if any(b[:28]):
        invalid()
    return int.from_bytes(b, 'big')


def decode_one(typ, data, offset):
    kind = typ.kind
    if kind in ('uint', 'int'):
        return Token(kind, int.from_bytes(take(data, offset, 32), 'big')), offset + 32
    if kind == 'address':
        return Token(kind, take(data, offset, 32)[12:]), offset + 32
    if kind == 'bool':
        b = take(data, offset, 32)
        if any(b[:31]):
            invalid()
        return Token(kind, b[31] == 1), offset + 32
    if kind == 'fixedbytes':
        return Token(kind, take(data, offset, typ.size)), offset + ((typ.size + 31) // 32) * 32
    if kind in ('bytes', 'string'):
        start = offset_word(data, offset)
        length = offset_word(data, start)
        value = take(data, start + 32, length)
        if kind == 'string':
            value = value.decode('utf-8', 'replace')
        return Token(kind, value), offset + 32
    if kind == 'array':
        start = offset_word(data, offset)
        length = offset_word(data, start)
        # Guard sizes independently of the input to avoid hostile allocations.
        if length > max(100000, len(data) * 32):
            invalid()
        subdata = data[start + 32:]
        values = []
        cursor = 0
        for _ in range(length):
            v, cursor = decode_one(typ.children[0], subdata, cursor)
            values.append(v)
        return Token(kind, values), offset + 32
    if typ.dynamic():
        start = offset_word(data, offset)
        if start > len(data):
            invalid()
        subdata = data[start:]
        cursor = 0
    else:
        subdata, cursor = data, offset
    if kind == 'fixedarray':
        if typ.size > max(100000, len(data) * 32):
            invalid()
        children = [typ.children[0]] * typ.size
    else:
        children = typ.children
    values = []
    for child in children:
        v, cursor = decode_one(child, subdata, cursor)
        values.append(v)
    return Token(kind, values), (offset + 32 if typ.dynamic() else cursor)


def decode(types, data):
    if not data and any(not (t.kind in ('fixedbytes', 'fixedarray') and t.size == 0) for t in types):
        raise AbiError(EMPTY_ERROR)
    values = []
    cursor = 0
    for typ in types:
        value, cursor = decode_one(typ, data, cursor)
        values.append(value)
    return values
PY
