    start = 1
    level = 0
    quoted = False
    for i, c in enumerate(s):
        if c == '"':
            quoted = not quoted
        elif not quoted:
            if c in '[(':
                level += 1
            elif c in '])':
                level -= 1
                if level == 0:
                    result.append(s[start:i])
                    start = i + 1
            elif c == ',' and level == 1:
                result.append(s[start:i])
                start = i + 1
