"""The Keccak-256 sponge used for Ethereum's ABI signature hashes."""
MASK = (1 << 64) - 1
ROTATION = (
    (0, 36, 3, 41, 18),
    (1, 44, 10, 45, 2),
    (62, 6, 43, 15, 61),
    (28, 55, 25, 21, 56),
    (27, 20, 39, 8, 14),
)
ROUND_CONSTANTS = (
    0x0000000000000001, 0x0000000000008082, 0x800000000000808a,
    0x8000000080008000, 0x000000000000808b, 0x0000000080000001,
    0x8000000080008081, 0x8000000000008009, 0x000000000000008a,
    0x0000000000000088, 0x0000000080008009, 0x000000008000000a,
    0x000000008000808b, 0x800000000000008b, 0x8000000000008089,
    0x8000000000008003, 0x8000000000008002, 0x8000000000000080,
    0x000000000000800a, 0x800000008000000a, 0x8000000080008081,
    0x8000000000008080, 0x0000000080000001, 0x8000000080008008,
)


def rotate(value, amount):
    return ((value << amount) | (value >> (64 - amount))) & MASK


def permutation(state):
    for rc in ROUND_CONSTANTS:
        parity = [state[x] ^ state[x + 5] ^ state[x + 10] ^ state[x + 15] ^ state[x + 20] for x in range(5)]
        delta = [parity[(x - 1) % 5] ^ rotate(parity[(x + 1) % 5], 1) for x in range(5)]
        for x in range(5):
            for y in range(5):
                state[x + 5 * y] ^= delta[x]
        lanes = [0] * 25
        for x in range(5):
            for y in range(5):
                lanes[y + 5 * ((2 * x + 3 * y) % 5)] = rotate(state[x + 5 * y], ROTATION[x][y])
        for x in range(5):
            for y in range(5):
                state[x + 5 * y] = lanes[x + 5 * y] ^ ((~lanes[(x + 1) % 5 + 5 * y]) & lanes[(x + 2) % 5 + 5 * y])
        state[0] ^= rc


def keccak256(data):
    rate = 136
    message = bytearray(data)
    remaining = rate - len(message) % rate
    if remaining == 1:
        message.append(0x81)
    else:
        message.extend(b'\x01' + b'\0' * (remaining - 2) + b'\x80')
    state = [0] * 25
    for base in range(0, len(message), rate):
        block = message[base:base + rate]
        for i in range(rate // 8):
            state[i] ^= int.from_bytes(block[8 * i:8 * i + 8], 'little')
        permutation(state)
    return b''.join(x.to_bytes(8, 'little') for x in state)[:32]
