def bool_field(obj, key, default=None):
    val = obj.get(key, default)
    if key not in obj and default is None:
        required(obj, key)
    if not isinstance(val, bool):
        expected(val, 'a boolean')
    return val


def json_type(obj):
    s = string_field(obj, 'type')
    try:
        typ = parse_type(s)
    except AbiError as error:
        raise JsonProblem(str(error).split('\n')[0])
    def components(t):
        if t.kind == 'tuple':
            fields = required(obj, 'components')
            if not isinstance(fields, list):
                expected(fields, 'a sequence')
            return Type('tuple', children=tuple(parameter(f).typ for f in fields))
        if t.kind in ('array', 'fixedarray'):
            return Type(t.kind, t.size, (components(t.children[0]),))
        return t
