    if not isinstance(obj, dict):
        expected(obj, 'struct EventParam' if event else 'struct Param')
    name = string_field(obj, 'name')
    typ = json_type(obj)
    indexed = bool_field(obj, 'indexed', False) if event else False
    return Parameter(name, typ, indexed)


