    values = required(obj, key)
    if not isinstance(values, list):
        expected(values, 'a sequence')
    return [parameter(p, event) for p in values]


def operation(obj):
    kind = obj['type']
    if kind in ('fallback', 'receive'):
        return Operation(kind, '', [], [])
    # All fields of an operation are read before missing fields are diagnosed.
    # Parse present fields in document order first.
    parsed = {}
