        if key == 'name' and kind != 'constructor':
            parsed[key] = string_field(obj, key)
        elif key == 'inputs':
            parsed[key] = parameters(obj, key, kind == 'event')
        elif key == 'outputs' and kind == 'function':
            parsed[key] = parameters(obj, key)
        elif key == 'anonymous' and kind == 'event':
            parsed[key] = bool_field(obj, key)
        elif key == 'constant' and kind == 'function' and value is not None:
            bool_field(obj, key)
