        detail = 'key must be a string'
    elif msg == "Expecting ':' delimiter":
        detail = 'expected `:`'
    elif msg == "Expecting ',' delimiter":
        detail = 'expected `,` or `]`'
    elif msg == 'Extra data':
        detail = 'trailing characters'
