            serialization(text, 'EOF while parsing a list', pos)
        if text[pos] == ']':
            # The stream loader deliberately does not consume trailing data.
            return operations
        try:
            obj, end = decoder.raw_decode(text, pos)
        except json.JSONDecodeError as error:
            json_syntax(text, error)
        if not isinstance(obj, dict):
            serialization(text, 'invalid type: ' + value_description(obj) + ', expected internally tagged enum Operation', end)
        if 'type' not in obj:
            serialization(text, 'missing field `type`', end)
        kind = obj['type']
        if kind not in ('constructor', 'function', 'event', 'error', 'fallback', 'receive'):
            # Tag errors originate at the tag rather than at the closing brace.
            match = re.search(r'"type"\s*:\s*', text[pos:end])
            tag_end = end
            if match:
                try:
                    _, tag_end = decoder.raw_decode(text, pos + match.end())
                except json.JSONDecodeError:
                    pass
            if isinstance(kind, str):
                detail = ('unknown variant `' + kind + '`, expected one of `constructor`, `function`, `event`, `error`, `fallback`, `receive`')
            else:
                detail = 'invalid type: ' + value_description(kind) + ', expected variant identifier'
            serialization(text, detail, tag_end)
        try:
            operations.append(operation(obj))
        except JsonProblem as error:
            serialization(text, str(error), end)
        pos = end
        while pos < len(text) and text[pos] in ' \n\r\t':
            pos += 1
        if pos >= len(text):
            serialization(text, 'EOF while parsing a list', pos)
        if text[pos] == ']':
            return operations
        if text[pos] != ',':
            serialization(text, 'expected `,` or `]`', pos + 1)
        pos += 1
        p = pos
        while p < len(text) and text[p] in ' \n\r\t':
            p += 1
        if p < len(text) and text[p] == ']':
            serialization(text, 'trailing comma', p + 1)


def select(operations, name, kind):
    short = name.split('(', 1)[0]
    choices = [op for op in operations if op.kind == kind and op.name == short]
    if not choices:
        raise AbiError('Invalid name: ' + short)
    if '(' in name:
        for op in choices:
            if op.signature() == name:
                return op
        raise AbiError('invalid ' + kind + ' signature `' + name + '`')
    if len(choices) != 1:
        raise AbiError('More than one function found for name `' + name + '`, try providing the full signature')
    return choices[0]


def topic_bytes(text):
    # Hash inputs accept a prefix and whitespace, but always denote 32 bytes.
    if text.startswith('0x'):
        text = text[2:]
    raw = text.encode('utf-8', 'surrogateescape')
    for i, c in enumerate(raw):
        if c not in b'0123456789ABCDEFabcdef':
            raise AbiError(f'Invalid character {rust_char(chr(c))} at position {i}')
    if len(raw) != 64:
        raise AbiError('Invalid input length')
    return bytes.fromhex(text)


def decode_event(event, topics, data):
    indexed = [p for p in event.inputs if p.indexed]
    regular = [p for p in event.inputs if not p.indexed]
    if not event.anonymous:
        if not topics or topics[0] != event.hash():
            invalid()
        topics = topics[1:]
    # Indexed composites and strings are represented by their Keccak digest.
    types = [Type('fixedbytes', 32) if p.typ.kind in ('array', 'fixedarray', 'tuple', 'string', 'bytes') else p.typ for p in indexed]
    indexed_values = decode(types, b''.join(topics))
    if len(topics) != len(indexed):
        invalid()
    values = decode([p.typ for p in regular], data)
    result = {p.name: v for p, v in zip(indexed + regular, indexed_values + values)}
    return [(p.name, result[p.name]) for p in event.inputs]
