    ('encode', 'function'): ['abi-path', 'function-name-or-signature'],
    ('decode', 'function'): ['abi-path', 'function-name-or-signature', 'data'],
    ('decode', 'params'): ['data'],
    ('decode', 'log'): ['abi-path', 'event-name-or-signature', 'data'],
    ('encode', 'params'): [],
}
OPTIONS = {
    ('encode', 'function'): ('p', 'params', 1),
    ('encode', 'params'): ('v', 'type-or-param', 2),
    ('decode', 'params'): ('t', 'type', 1),
    ('decode', 'log'): ('l', 'topic', 1),
}


def prefix(path):
    return ' '.join((PROGRAM,) + tuple(path))


def heading(path):
    return ('ethabi-cli' if not path else '-'.join((PROGRAM,) + tuple(path))) + ' ' + VERSION


def has_lenient(path):
    return len(path) == 2 and path[0] == 'encode'


def option_display(path):
    if path not in OPTIONS:
        return ''
    short, name, count = OPTIONS[path]
    return ('-' + short + ' ' + ' '.join('<' + name + '>' for _ in range(count)) + ('' if count == 2 else '...'))


