    cmd = prefix(path)
    if len(path) < 2:
        return cmd + ' <SUBCOMMAND>'
    names = ['<' + n + '>' for n in POSITIONALS[path]]
    if seen:
        if 'lenient' in seen:
            cmd += ' --lenient'
        cmd += ''.join(' ' + n for n in names)
        if 'option' in seen:
            cmd += ' ' + option_display(path)
        return cmd
    if has_lenient(path):
        cmd += ' [FLAGS]'
    if path in OPTIONS:
        cmd += ' [OPTIONS]'
    cmd += ''.join(' ' + n for n in names)
    return cmd


def help_text(path, long=False):
    head = heading(path) + '\n' + DESCRIPTIONS[path] + '\n\nUSAGE:\n    ' + usage(path) + '\n'
    if path == ('encode', 'params') and long:
        return head + '''
FLAGS:
    -h, --help       
            Prints help information

    -l, --lenient    
            Allow short representation of input params (numbers are in decimal form)

    -V, --version    
            Prints version information


OPTIONS:
    -v <type-or-param> <type-or-param>        
            Pairs of types directly followed by params in the form:

            -v <type1> <param1> -v <type2> <param2> ...
'''
    head += '\nFLAGS:\n    -h, --help       Prints help information\n'
    if has_lenient(path):
        head += '    -l, --lenient    Allow short representation of input params'
        if path[-1] == 'params':
            head += ' (numbers are in decimal form)'
        head += '\n'
    head += '    -V, --version    Prints version information\n'
    if len(path) < 2:
        head += '\nSUBCOMMANDS:\n'
        if not path:
            head += '    decode    Decode ABI call result\n    encode    Encode ABI call\n    help      Prints this message or the help of the given subcommand(s)\n'
        else:
            head += '    function    Load function from JSON ABI file\n    help        Prints this message or the help of the given subcommand(s)\n'
            if path[0] == 'decode':
                head += '    log         Decode event log\n'
            head += '    params      Specify types of input params inline\n'
        return head
    if path in OPTIONS:
        head += '\nOPTIONS:\n    ' + option_display(path) + '        '
        if path == ('encode', 'params'):
            head += 'Pairs of types directly followed by params in the form:'
        head += '\n'
