OPTIONS = {
    ('encode', 'function'): ('p', 'params', 1),
    ('encode', 'params'): ('v', 'type-or-param', 2),
    ('decode', 'params'): ('t', 'type', 1),
    ('decode', 'log'): ('l', 'topic', 1),
}


def prefix(path):
    return ' '.join((PROGRAM,) + tuple(path))


def heading(path):
    return ('ethabi-cli' if not path else '-'.join((PROGRAM,) + tuple(path))) + ' ' + VERSION


def has_lenient(path):
    return len(path) == 2 and path[0] == 'encode'


def option_display(path):
    if path not in OPTIONS:
        return ''
    short, name, count = OPTIONS[path]
    return ('-' + short + ' ' + ' '.join('<' + name + '>' for _ in range(count)) + ('' if count == 2 else '...'))


def usage(path, seen=None):
    cmd = prefix(path)
    if len(path) < 2:
        return cmd + ' <SUBCOMMAND>'
    names = ['<' + n + '>' for n in POSITIONALS[path]]
    if seen:
        if 'lenient' in seen:
            cmd += ' --lenient'
        cmd += ''.join(' ' + n for n in names)
        if 'option' in seen:
            cmd += ' ' + option_display(path)
        return cmd
    if has_lenient(path):
        cmd += ' [FLAGS]'
    if path in OPTIONS:
        cmd += ' [OPTIONS]'
    cmd += ''.join(' ' + n for n in names)
    return cmd


def help_text(path, long=False):
    head = heading(path) + '\n' + DESCRIPTIONS[path] + '\n\nUSAGE:\n    ' + usage(path) + '\n'
    if path == ('encode', 'params') and long:
        return head + '''
FLAGS:
    -h, --help       
            Prints help information

    -l, --lenient    
            Allow short representation of input params (numbers are in decimal form)

    -V, --version    
            Prints version information


OPTIONS:
    -v <type-or-param> <type-or-param>        
            Pairs of types directly followed by params in the form:

            -v <type1> <param1> -v <type2> <param2> ...
'''
    head += '\nFLAGS:\n    -h, --help       Prints help information\n'
    if has_lenient(path):
        head += '    -l, --lenient    Allow short representation of input params'
        if path[-1] == 'params':
            head += ' (numbers are in decimal form)'
        head += '\n'
    head += '    -V, --version    Prints version information\n'
    if len(path) < 2:
        head += '\nSUBCOMMANDS:\n'
        if not path:
            head += '    decode    Decode ABI call result\n    encode    Encode ABI call\n    help      Prints this message or the help of the given subcommand(s)\n'
        else:
            head += '    function    Load function from JSON ABI file\n    help        Prints this message or the help of the given subcommand(s)\n'
            if path[0] == 'decode':
                head += '    log         Decode event log\n'
            head += '    params      Specify types of input params inline\n'
        return head
    if path in OPTIONS:
        head += '\nOPTIONS:\n    ' + option_display(path) + '        '
        if path == ('encode', 'params'):
            head += 'Pairs of types directly followed by params in the form:'
        head += '\n'
    names = POSITIONALS[path]
    if names:
        width = max(len(n) + 2 for n in names) + 4
        head += '\nARGS:\n'
        for name in names:
            head += '    ' + ('<' + name + '>').ljust(width) + '\n'
    return head


class CliExit(Exception):
    def __init__(self, text='', code=0, stderr=False):
        self.text, self.code, self.stderr = text, code, stderr


def cli_error(message, path, seen=None):
    raise CliExit('error: ' + message + '\n\nUSAGE:\n    ' + usage(path, seen) + '\n\nFor more information try --help\n', 1, True)


def jaro(a, b):
    if a == b:
        return 1.0
    if not a or not b:
        return 0.0
    distance = max(len(a), len(b)) // 2 - 1
    am, bm = [False] * len(a), [False] * len(b)
    for i, c in enumerate(a):
        for j in range(max(0, i - distance), min(len(b), i + distance + 1)):
            if not bm[j] and b[j] == c:
                am[i], bm[j] = True, True
                break
    n = sum(am)
    if n == 0:
        return 0.0
    aa = [c for c, matched in zip(a, am) if matched]
    bb = [c for c, matched in zip(b, bm) if matched]
    swaps = sum(x != y for x, y in zip(aa, bb)) / 2
    score = (n / len(a) + n / len(b) + (n - swaps) / n) / 3
    prefix_size = 0
    for x, y in zip(a[:4], b[:4]):
        if x != y:
            break
        prefix_size += 1)
    return score + prefix_size * 0.1 * (1 - score)


def suggestion(word, choices):
    scored = [(jaro(word, c), c) for c in choices]
    good = [(v, c) for v, c in scored if v > 0.8]
    return max(good)[1] if good else None


def children(path):
    if not path:
        return ['decode', 'encode', 'help']
    if len(path) == 1:
        return ['function', 'help', 'params'] + (['log'] if path[0] == 'decode' else [])
    return []


def unexpected(arg, path, seen, remaining=None):
    message = "Found argument '" + arg + "' which wasn't expected, or isn't valid in this context"
    if len(path) < 2 and not arg.startswith('-'):
        guess = suggestion(arg, children(path))
        if guess:
            msg = ("The subcommand '" + arg + "' wasn't recognized\n\tDid you mean '" + guess + "'?\n\n"
