    if arg.startswith('--'):
        longopts = ['help', 'version'] + (['lenient'] if has_lenient(path) else [])
        guess = suggestion(arg[2:], longopts)
        if guess:
            message += '\n\tDid you mean \x1b[32m--\x1b[0m\x1b[32m' + guess + '\x1b[0m?'
