        elif piece in children(target):
            target += (piece,)
            continue
        raise CliExit("error: The subcommand '" + piece + "' wasn't recognized\n\nUSAGE:\n\t" + prefix(path) + ' help <subcommands>...\n\nFor more information try --help\n', 1, True)
