def parse_cli(args):
    path = ()
    pos = []
    vals = []
    seen = set()
    lenient = False
    pending = 0
    noflags = False
    i = 0
    while i < len(args):
        arg = args[i]
        i += 1
        allow_hyphen = path == ('encode', 'params')
        if pending and (allow_hyphen or not arg.startswith('-') or arg == '-'):
            vals.append(arg)
            pending -= 1
            continue
        pending = 0
        if not noflags and arg == '--':
            noflags = True
            continue
        if not noflags and (arg.startswith('--') or (arg.startswith('-') and arg != '-')):
            if arg.startswith('--'):
                longname = arg[2:].split('=', 1)[0]
                if longname == 'help':
                    raise CliExit(help_text(path, long=True))
                if longname == 'version':
                    raise text_version(path)
                if longname == 'lenient' and has_lenient(path):
                    if lenient:
                        cli_error("The argument '--lenient' was provided more than once, but cannot be used multiple times", path, seen)
                    lenient = True
                    seen.add('lenient')
                    continue
                unexpected('--' + longname, path, seen, args[i:])
            shortargs = arg[1:]
            offset = 0
            while offset < len(shortargs):
                flag = shortargs[offset]
                offset += 1
                if flag == 'h':
                    raise CliExit(help_text(path))
                if flag == 'V':
                    raise text_version(path)
                if flag == 'l' and has_lenient(path):
                    if lenient:
                        cli_error("The argument '--lenient' was provided more than once, but cannot be used multiple times", path, seen)
                    lenient = True
                    seen.add('lenient')
                elif path in OPTIONS and flag == OPTIONS[path][0]:
                    seen.add('option')
                    count = OPTIONS[path][2]
                    attached = shortargs[offset:]
                    if attached:
                        vals.append(attached[1:] if attached.startswith('=') else attached)
                        pending = 0 if '=' in attached else count - 1
                    else:
