            if arg == 'help':
                raise CliExit(requested_help(path, args[i:]))
            if arg in children(path):
                path += (arg,)
                seen = set()
                continue
            unexpected(arg, path, seen, args[i:])
        if len(pos) < len(POSITIONALS[path]):
            pos.append(arg)
        else:
            unexpected(arg, path, seen, args[i:])
    if len(path) < 2:
        raise CliExit(help_text(path), 1, True)
    missing = POSITIONALS[path][len(pos):]
    if missing:
        cli_error('The following required arguments were not provided:\n' + '\n'.join('    <' + s + '>' for s in missing), path, seen)
    if 'option' in seen and not vals:
        cli_error("The argument '" + option_display(path) + "' requires a value but none was supplied", path, seen)
    if path == ('encode', 'params') and len(vals) % 2:
        cli_error("The argument '" + option_display(path) + "' requires 2 values, but 1 was provided", path, seen)
    return path, pos, vals, lenient


def text_version(path):
    return CliExit(heading(path) + '\n')


def execute(path, pos, vals, lenient):
    direction, mode = path
    if mode == 'params':
        if direction == 'encode':
            types = [parse_type(t) for t in vals[::2]]
            tokens = [tokenize(t, value, lenient) for t, value in zip(types, vals[1::2])]
            return encode(tokens).hex()
        types = [parse_type(t) for t in vals]
        data = unhex(pos[0])
        return '\n'.join(str(t) + ' ' + str(v) for t, v in zip(types, decode(types, data)))
    contract = load_contract(pos[0])
    operation = select(contract, pos[1], 'event' if mode == 'log' else 'function')
    if direction == 'encode':
        tokens = [tokenize(p.typ, v, lenient) for p, v in zip(operation.inputs, vals)]
        if len(tokens) != len(operation.inputs):
            invalid()
        return operation.hash()[:4].hex() + encode(tokens).hex()
    if mode == 'function':
        data = unhex(pos[2])
        types = [p.typ for p in operation.outputs]
        return '\n'.join(str(t) + ' ' + str(v) for t, v in zip(types, decode(types, data)))
    topics = [topic_bytes(s) for s in vals]
    data = unhex(pos[2])
    return '\n'.join(name + ' ' + str(v) for name, v in decode_event(operation, topics, data))


def main():
    try:
        path, pos, vals, lenient = parse_cli(sys.argv[1:])
        print(execute(path, pos, vals, lenient))
        return 0
    except CliExit as exit:
        (sys.stderr if exit.stderr else sys.stdout).write(exit.text)
        return exit.code
    except AbiError as error:
        sys.stderr.write('Error: ' + str(error) + '\n')
        return 1
    except (RecursionError, OverflowError, ValueError):
        sys.stderr.write('Error: Invalid data\n')
        return 1


if __name__ == '__main__':
    sys.exit(main())
